import sys

def solve(n, k):
    if k > n // 2 - 1:
        return -1
    pairs = []
    remaining = list(range(n))
    while remaining:
        a = remaining.pop()
        for b in remaining:
            if a & b == k:
                pairs.append((a, b))
                remaining.remove(b)
                break
        else:
            return -1
    return pairs

def main():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        n, k = map(int, input[index].split())
        index += 1
        result = solve(n, k)
        if result == -1:
            results.append('-1')
        else:
            results.extend(f"{a} {b}" for a, b in result)
    print("\n".join(results))

if __name__ == "__main__":
    main()
